        private double[] GetRiskFactorsData(Tb_registos reading)
        {
            // Keep risk levels in their original 1-3 scale
            double tempRisk = reading.risco_temperatura;
            double humidityRisk = reading.risco_humidade;

            // Convert radiation to a 1-3 scale
            double radiationMax = 1023.0; // Maximum possible radiation value
            double radiationNormalized = reading.radiacao / radiationMax;
            double radiationRisk = 1 + (radiationNormalized * 2); // Maps 0-1 to 1-3

            return new double[] { tempRisk, humidityRisk, radiationRisk };
        }

