        private int CalculateRadiationRisk(double radiation)
        {
            // Define thresholds for radiation risk levels
            // Assuming average radiation is 500, we'll set thresholds accordingly
            if (radiation < 300) return 1; // Low risk
            else if (radiation < 700) return 2; // Medium risk
            else return 3; // High risk
        }

