        private void SetupHistoricalChart()
        {
            if (historicalData == null || !historicalData.Any())
                return;

            // Ordenar os dados por data/hora
            var orderedData = historicalData.OrderBy(x => x.data_registo).ToList();

            // Filtrar dados com base no período selecionado
            var filteredData = currentPeriod switch
            {
                PeriodType.Hour => orderedData.Where(x => x.data_registo >= DateTime.Now.AddHours(-1)).ToList(),
                PeriodType.Day => orderedData.Where(x => x.data_registo >= DateTime.Now.AddDays(-1)).ToList(),
                PeriodType.Week => orderedData.Where(x => x.data_registo >= DateTime.Now.AddDays(-7)).ToList(),
                _ => orderedData.Where(x => x.data_registo >= DateTime.Now.AddHours(-1)).ToList()
            };

            // Se não houver dados suficientes, use os últimos registros disponíveis
            if (!filteredData.Any())
            {
                filteredData = orderedData.TakeLast(Math.Min(orderedData.Count, 20)).ToList();
            }

            // Definir o número de pontos a mostrar no gráfico
            int pointsToShow = currentPeriod switch
            {
                PeriodType.Hour => 12,  // One point every 5 minutes
                PeriodType.Day => 12,   // One point every 2 hours (reduced from 24)
                PeriodType.Week => 14,  // Two points per day (reduced from 21)
                _ => 12
            };

            // Agrupar dados para reduzir a quantidade de pontos no gráfico
            var groupedData = GroupDataByPeriod(filteredData, pointsToShow);

            // Preparar rótulos para o eixo X
            historicalLabels = groupedData.Select(g => FormatDateLabel(g.Key, currentPeriod)).ToArray();

            // Preparar séries de dados
            var riskValues = groupedData.Select(g => g.Average(x => x.risco_incendio * 100)).ToArray();
            var tempValues = groupedData.Select(g => g.Average(x => x.temperatura)).ToArray();
            var humidityValues = groupedData.Select(g => g.Average(x => x.humidade)).ToArray();

            historicalSeries = new List<ChartSeries>
        {
            new ChartSeries { Name = "Risco de Incêndio (%)", Data = riskValues },
            new ChartSeries { Name = "Temperatura (°C)", Data = tempValues },
            new ChartSeries { Name = "Humidade (%)", Data = humidityValues }
        };
        }

        private IEnumerable<IGrouping<DateTime, Tb_registos>> GroupDataByPeriod(List<Tb_registos> data, int targetPoints)
        {
            if (data.Count <= targetPoints)
            {
                // Se temos menos pontos que o desejado, use cada ponto individualmente
                return data.GroupBy(x => x.data_registo);
            }

            // Determine o intervalo de tempo total
            var startTime = data.Min(x => x.data_registo);
            var endTime = data.Max(x => x.data_registo);
            var totalTimeSpan = endTime - startTime;

            // Calcule o intervalo para cada grupo
            var intervalPerGroup = TimeSpan.FromTicks(totalTimeSpan.Ticks / targetPoints);

            // Agrupe os dados por intervalo
            return data.GroupBy(x => RoundToInterval(x.data_registo, startTime, intervalPerGroup));
        }



        private DateTime RoundToInterval(DateTime date, DateTime startTime, TimeSpan interval)
        {
            var ticksFromStart = date.Ticks - startTime.Ticks;
            var intervals = (long)(ticksFromStart / interval.Ticks);
            return new DateTime(startTime.Ticks + intervals * interval.Ticks);
        }

        private string FormatDateLabel(DateTime date, PeriodType period)
        {
            return period switch
            {
                PeriodType.Hour => date.ToString("HH:mm"),
                PeriodType.Day => date.ToString("HH") + "h", // Just show the hour with 'h' suffix
                PeriodType.Week => date.ToString("dd/MM"), // Keep as is or could use "d/M" for even more compact
                _ => date.ToString("HH:mm")
            };
        }

